script:
project_name = frappe.form_dict.get('project_name')
total = 0
count = 0

# Lấy danh sách Journal Entry có docstatus = 1 (đã submit)
journal_entries = frappe.get_all("Journal Entry", filters={"docstatus": 1}, fields=["name"])

for je in journal_entries:
    doc = frappe.get_doc("Journal Entry", je.name)

    # Kiểm tra điều kiện: phải có cả 2 loại account
    has_account_6271 = False
    has_account_3349 = False

    # Duyệt qua tất cả rows để kiểm tra điều kiện
    for row in doc.accounts:
        if row.account == "6221 - Chi phí nhân công trực tiếp - PhuChau88":
            has_account_6271 = True
        elif row.account == "3349 - Bảng lương phải trả - PhuChau88":
            has_account_3349 = True

    # Chỉ xử lý nếu Journal Entry có cả 2 loại account
    if has_account_6271 and has_account_3349:
        # Duyệt lại để tính toán cho những rows có project đúng và account = 6271
        for row in doc.accounts:
            if row.project == project_name and row.account == "6221 - Chi phí nhân công trực tiếp - PhuChau88":
                debit = float(row.debit or 0)
                credit = float(row.credit or 0)
                total = total + debit - credit
                count = count + 1
frappe.response["message"] = {"total": total, "matched_rows": count}

# Server Script (Event: Before Save)
if doc.cost_center:
    for expense in doc.expenses:
        expense.cost_center = doc.cost_center

if doc.is_opening == 1 and doc.opening_date:
    exists = frappe.db.exists(
        "Hoa Don Ra Vao",
        {
            "is_opening": 1,
            "opening_date": doc.opening_date,
            "docstatus": 1,  # ✅ Chỉ kiểm tra với các bản ghi đã submit
            "name": ["!=", doc.name]  # Tránh trùng chính mình (khi update)
        }
    )
    if exists:
        frappe.throw(f"Opening VAT đã tồn tại cho ngày: {doc.opening_date}")
